// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
// makes them a member with the invite's role and gives them a first API key. An unknown or revoked token is ErrNotFound,
// a token used before is ErrInviteUsed and one used after its time ran out is ErrInviteExpired.
func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	var inv Invite
	found := false
	if token != "" {
		hash := HashToken(token)
		for _, i := range s.invites {
			if i.TokenHash == hash {
				inv, found = i, true
				break
			}
		}
	}
	if !found || inv.RevokedAt != nil {
		return User{}, Member{}, APIKey{}, ErrNotFound
	}
	if inv.AcceptedAt != nil {
		return User{}, Member{}, APIKey{}, ErrInviteUsed
	}
	if now.After(inv.ExpiresAt) {
		return User{}, Member{}, APIKey{}, ErrInviteExpired
	}

