		t.Fatalf("another address's invite: %v", err)
	}
	if _, _, _, err := s.AcceptInvite(fresh, "Ann", later); err != nil {
		t.Fatalf("the newest token: %v", err)
	}
}

func TestPendingInvites(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	accepted, _, _ := s.IssueInvite(o.ID, "a@people.example", RoleMember, "", t0)
	revoked, _, _ := s.IssueInvite(o.ID, "b@people.example", RoleMember, "", t0)
	expired, _, _ := s.IssueInvite(o.ID, "c@people.example", RoleMember, "", t0)
	fresh, _, _ := s.IssueInvite(o.ID, "d@people.example", RoleMember, "", t0.Add(InviteTTL))
	now := t0.Add(InviteTTL + time.Hour)
	if _, _, _, err := s.AcceptInvite(accepted.ID, "", now); err == nil {
		t.Fatal("accepting by ID worked")
	}
	tokenOf := func(email string) string { t.Helper(); return "" }
	_ = tokenOf
	if _, _, _, err := s.AcceptInvite("", "", now); err == nil {
		t.Fatal("empty token worked")
	}
	if _, err := s.RevokeInvite(o.ID, revoked.ID, now); err != nil {
		t.Fatal(err)
	}
	_ = expired
	_ = fresh
	pending := s.PendingInvites(o.ID, now)
	if len(pending) != 1 || pending[0].Email != "d@people.example" {
		t.Fatalf("pending = %+v, want only the fresh invite", pending)
	}
}
